import{effectiveStoryEdges,movementNames,reachableStory}from'./native-story.js';
const BASE=0x08000000,names=new Map(movementNames().map(n=>[n.code,n.name]));
export const actorColor=id=>['#2079b0','#ae3976','#147f67','#9258ae','#b66b12','#a84735'][Math.abs(id)%6];
export function traceMovement(bytes,start){let p=start&&{...start},path=p?[{...p}]:[],unknown=[];for(const code of bytes){if(code===254)break;const name=names.get(code)||'Unknown '+code,m=/^(walk_(?!in_place)|jump_(?:2_|1_)?)(.*)(down|up|left|right)$/.exec(name);if(m&&p){const amount=name.startsWith('jump_2_')?2:1;p={x:p.x+(m[3]==='right'?amount:m[3]==='left'?-amount:0),y:p.y+(m[3]==='down'?amount:m[3]==='up'?-amount:0)};path.push({...p});}else if(!m&&!/^(face|delay|walk_in_place|step_end|jump_in_place|emote|lock_facing|unlock_facing|disable|restore|hide|show|pause|enable|set_|clear_)/.test(name)){unknown.push(name);p=null;}}return{path,end:p,unknown};}
export function pathMovement(points){const byName=new Map(movementNames().map(n=>[n.name,n.code])),bytes=[];for(let i=1;i<points.length;i++){let{x,y}=points[i-1],to=points[i];if(![x,y,to.x,to.y].every(Number.isInteger))throw Error('Choose whole map tiles.');if(x!==to.x&&y!==to.y)throw Error('Draw horizontal or vertical segments.');while(x!==to.x||y!==to.y){const dir=to.x>x?'right':to.x<x?'left':to.y>y?'down':'up',code=byName.get('walk_'+dir);if(code===undefined)throw Error('This engine has no verified walking command.');bytes.push(code);x+=dir==='right'?1:dir==='left'?-1:0;y+=dir==='down'?1:dir==='up'?-1:0;if(bytes.length>511)throw Error('Use up to 511 movement actions.');}}return[...bytes,254];}
// Positions are propagated through branches and call/return contexts. Conflicting
// positions merge to unknown; native calls can move actors, so invalidate them.
export function sceneMapModel(graph,root,nativeMap,npcs,{maxStates=6000}={}){const reachable=[...reachableStory(graph,root.address)],actors=npcs.map(n=>({id:n.localId,label:'Character '+n.localId,x:n.x,y:n.y,color:actorColor(n.localId)})),positions=Object.fromEntries(actors.map(a=>[a.id,{x:a.x,y:a.y}])),entry=npcs.find(n=>root.kind==='npcs'&&n.index===root.index),rootActor=entry?.localId??null;if(Number.isInteger(root.x)&&Number.isInteger(root.y)&&root.kind==='triggers')positions[255]={x:root.x,y:root.y};actors.push({id:255,label:'Player',...positions[255],color:actorColor(255)});const work=[{at:root.address,stack:[],positions}],states=new Map(),routes=new Map();let processed=0,truncated=false;const merge=(a,b)=>{const r={};for(const id of new Set([...Object.keys(a),...Object.keys(b)])){const x=a[id],y=b[id];r[id]=x&&y&&x.x===y.x&&x.y===y.y?x:null;}return r;};
 while(work.length){if(++processed>maxStates){truncated=true;break;}const s=work.shift(),n=graph.nodes[s.at];if(!n)continue;const key=s.at+':'+s.stack.join(','),previous=states.get(key),pos=previous?merge(previous,s.positions):s.positions;if(previous&&JSON.stringify(previous)===JSON.stringify(pos))continue;states.set(key,pos);let next=structuredClone(pos);const args=n.args?.map((a,i)=>graph.edits.commands?.[n.at]?.args[i]??a.value)||[],resolve=id=>id===254?rootActor:id,edges=effectiveStoryEdges(graph,n),ret=edges.find(e=>e.kind==='next'),calls=[4,7,9,11].includes(n.code)?edges.filter(e=>e.kind!=='next'):[];
 if(n.name==='applymovement'||n.name==='applymovementat'&&args[2]+'.'+args[3]===nativeMap.key){const id=resolve(args[0]),a=n.args.findIndex(a=>a.kind==='movement'),record=graph.movements[args[a]-BASE],bytes=record&&(graph.edits.movements[record.at]?.bytes??record.bytes);if(bytes){const trace=traceMovement(bytes,id===null?null:next[id]),routeKey=n.at+':'+(trace.path[0]?trace.path[0].x+','+trace.path[0].y:'unknown');routes.set(routeKey,{at:n.at,actor:id,bytes,record:record.at,...trace,color:actorColor(id??0)});if(id!==null)next[id]=trace.end;}}
 if(['setobjectxy','setobjectxyperm'].includes(n.name)){const id=resolve(args[0]);if(id!==null)next[id]={x:args[1],y:args[2]};}
 if(n.external||n.opaque){next=Object.fromEntries(Object.keys(next).map(id=>[id,null]));}
 if(n.code===3){if(s.stack.length)work.push({at:s.stack.at(-1),stack:s.stack.slice(0,-1),positions:next});continue;}
 if(calls.length){for(const e of calls){if(s.stack.length>=16){truncated=true;continue;}work.push({at:e.to,stack:ret?[...s.stack,ret.to]:s.stack,positions:next});}if([7,11].includes(n.code)&&ret)work.push({at:ret.to,stack:s.stack,positions:next});for(const e of edges.filter(e=>e!==ret&&!calls.includes(e)))work.push({at:e.to,stack:s.stack,positions:next});continue;}
 for(const e of edges)work.push({at:e.to,stack:s.stack,positions:next});
 }
 return{actors,routes:[...routes.values()],reachable,truncated,processed,rootActor,entry:{x:root.x??entry?.x,y:root.y??entry?.y},unknownRoutes:[...routes.values()].filter(r=>!r.path.length||r.unknown.length)};
}
